import{_ as t,o as a,c as i,ae as r}from"./chunks/framework.vXWZTEWX.js";const g=JSON.parse('{"title":"🛡️ Security & OWASP Standards - TenderCheck AI","description":"","frontmatter":{},"headers":[],"relativePath":"standards/security_policy.md","filePath":"standards/security_policy.md"}'),n={name:"standards/security_policy.md"};function o(s,e,c,l,d,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="🛡️-security-owasp-standards-tendercheck-ai" tabindex="-1">🛡️ Security &amp; OWASP Standards - TenderCheck AI <a class="header-anchor" href="#🛡️-security-owasp-standards-tendercheck-ai" aria-label="Permalink to &quot;🛡️ Security &amp; OWASP Standards - TenderCheck AI&quot;">​</a></h1><h2 id="_1-core-security-philosophy" tabindex="-1">1. Core Security Philosophy <a class="header-anchor" href="#_1-core-security-philosophy" aria-label="Permalink to &quot;1. Core Security Philosophy&quot;">​</a></h2><p>[cite_start]Security is integrated into every layer of the development lifecycle (DevSecOps), focusing on data integrity, privacy, and protection against both traditional and AI-specific vulnerabilities[cite: 712, 715].</p><h2 id="_2-input-validation-defense" tabindex="-1">2. Input Validation &amp; Defense <a class="header-anchor" href="#_2-input-validation-defense" aria-label="Permalink to &quot;2. Input Validation &amp; Defense&quot;">​</a></h2><ul><li>[cite_start]<strong>Schema Validation</strong>: All external inputs, including API requests and extracted document data, must be strictly validated using <strong>Zod</strong> or <strong>Valibot</strong>[cite: 171, 667].</li><li>[cite_start]<strong>Injection Prevention</strong>: Implement strict input sanitization and HTML encoding to mitigate XSS and injection risks[cite: 206, 217].</li><li>[cite_start]<strong>PDF Safety</strong>: Ensure the document processor handles potentially malicious PDF structures without executing embedded scripts[cite: 713].</li></ul><h2 id="_3-infrastructure-header-security" tabindex="-1">3. Infrastructure &amp; Header Security <a class="header-anchor" href="#_3-infrastructure-header-security" aria-label="Permalink to &quot;3. Infrastructure &amp; Header Security&quot;">​</a></h2><ul><li>[cite_start]<strong>Security Headers</strong>: Use <strong>Helmet.js</strong> to enforce Content Security Policy (CSP) and other protective headers in the Express backend[cite: 170, 218].</li><li>[cite_start]<strong>Environment Variables</strong>: Manage sensitive keys (OpenAI, Firebase) through secure <code>.env</code> files, validated at runtime to prevent configuration errors.</li><li><strong>Dependency Hygiene</strong>: Perform regular security audits using tools like <strong>Snyk</strong> or <strong>Dependabot</strong> to identify and patch vulnerable packages.</li></ul><h2 id="_4-owasp-top-10-for-llms-alignment" tabindex="-1">4. OWASP Top 10 for LLMs Alignment <a class="header-anchor" href="#_4-owasp-top-10-for-llms-alignment" aria-label="Permalink to &quot;4. OWASP Top 10 for LLMs Alignment&quot;">​</a></h2><ul><li>[cite_start]<strong>Prompt Injection Defense</strong>: Implement guardrails to prevent users from manipulating the AI’s logic through the uploaded documents[cite: 728].</li><li>[cite_start]<strong>Data Leakage Prevention</strong>: Ensure sensitive information from the Pliego or Offer is not inadvertently stored or exposed in logs[cite: 728].</li><li>[cite_start]<strong>Auditability &amp; Logging</strong>: Maintain a <code>DecisionLog</code> for every AI action to ensure transparency and accountability[cite: 808, 1240].</li></ul><h2 id="_5-authentication-privacy" tabindex="-1">5. Authentication &amp; Privacy <a class="header-anchor" href="#_5-authentication-privacy" aria-label="Permalink to &quot;5. Authentication &amp; Privacy&quot;">​</a></h2><ul><li>[cite_start]<strong>Secure Auth</strong>: Use <strong>JWT</strong> and <strong>Bcrypt</strong> for user authentication and secure session management[cite: 171, 668].</li><li>[cite_start]<strong>Privacy by Design</strong>: Adhere to GDPR and the EU AI Act by ensuring data minimization and providing clear explanations for AI-driven results[cite: 574, 950].</li></ul>',11)])])}const h=t(n,[["render",o]]);export{g as __pageData,h as default};
